def _regular_entry(path: Path, *, root: Path = ROOT) -> dict[str, Any]:
    relative = path.relative_to(root).as_posix() if path.is_relative_to(root) else str(path)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        digest = hashlib.sha256()
        while True:
            chunk = os.read(fd, 8 << 20)
            if not chunk:
                break
            digest.update(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    path_st = path.lstat()
    identity = (before.st_dev, before.st_ino, before.st_mode, before.st_uid,
                before.st_nlink, before.st_size)
    if (identity != (after.st_dev, after.st_ino, after.st_mode, after.st_uid,
                     after.st_nlink, after.st_size)
            or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
            or before.st_uid != os.getuid() or before.st_nlink != 1):
        raise ValueError(f"candidate/closure file identity drift: {path}")
    return {
        "path": relative, "type": "regular", "mode": stat.S_IMODE(before.st_mode),
        "uid": before.st_uid, "nlink": before.st_nlink, "size": before.st_size,
        "sha256": digest.hexdigest(), "verification_action": "content_rehash",
    }


def _path_present(path: Path) -> bool:
    return path.exists() or path.is_symlink()


def _write_all(fd: int, payload: bytes) -> None:
    """Write an exact payload or fail; os.write is permitted to short-write."""
    offset = 0
    while offset < len(payload):
        written = os.write(fd, payload[offset:])
        if written <= 0:
            raise OSError("zero-length write before payload completion")
        offset += written


def _regular_bytes(path: Path, *, mode: int, owner: int | None = None) -> bytes:
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        chunks = []
        while True:
            chunk = os.read(fd, 8 << 20)
            if not chunk:
                break
            chunks.append(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    path_st = path.lstat()
    expected_owner = os.getuid() if owner is None else owner
    if ((before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_nlink,
         before.st_size, before.st_mtime_ns, before.st_ctime_ns) !=
        (after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_nlink,
         after.st_size, after.st_mtime_ns, after.st_ctime_ns)
            or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
            or stat.S_IMODE(before.st_mode) != mode or before.st_uid != expected_owner
            or before.st_nlink != 1):
        raise ValueError(f"regular-file identity/mode/ownership drift: {path}")
    return b"".join(chunks)


def _read_root_json(root: Path, relative: str) -> Any:
    return base.strict_json_loads((root / relative).read_text(encoding="utf-8"))


def generic_config_projection(config: Mapping[str, Any]) -> dict[str, Any]:
    """Return the exact config schema accepted by the reviewed generic builders."""
    expected = set(GENERIC_CONFIG_KEYS) | set(SUCCESSOR_CONFIG_KEYS)
    if set(config) != expected:
        raise ValueError(f"successor config key mismatch: {sorted(set(config) ^ expected)}")
    return {key: config[key] for key in GENERIC_CONFIG_KEYS}


def generic_replay_bundle(bundle: Mapping[str, Any], generic_config_sha256: str) -> dict[str, Any]:
    expected = {"schema_version", "protocol_config_sha256", "replay_registry_sha256",
                "source_role", "source_revision", "partition", "observations"}
    if set(bundle) != expected:
        raise ValueError(f"successor replay-bundle key mismatch: {sorted(set(bundle) ^ expected)}")
    base.validate_sha256(generic_config_sha256, "generic protocol config SHA-256")
    return {**dict(bundle), "protocol_config_sha256": generic_config_sha256}


def _validate_m2_semantics(*, root: Path = ROOT) -> dict[str, Any]:
    prefix = "data/msae_independent_measurement_v3"
    task = _read_root_json(root, f"{prefix}/task_manifest.json")
    support = _read_root_json(root, f"{prefix}/support.json")
    templates = _read_root_json(root, f"{prefix}/prefix_templates.json")
    maps = _read_root_json(root, f"{prefix}/maps.json")
    matrix = _read_root_json(root, f"{prefix}/finite_pass_matrix.json")
    imports = _read_root_json(root, f"{prefix}/protocol_imports.json")
    if (task.get("schema_version") != "msae_v3_task_manifest_v1"
            or task.get("protocol_id") != PROTOCOL
            or task.get("roles") != list(base.ROLES) or task.get("tasks") != list(base.TASKS)
            or task.get("label_rows") != 1491748):
        raise ValueError("M2 task-manifest semantics drift")
    audit = task.get("amalgum_legacy_upos_repair", {}).get("audit", {})
    denominators = {name: [row.get("population_token_count"), row.get("correction_token_count")]
                    for name, row in audit.get("ledgers", {}).items()}
    if denominators != {"raw_selected": [290192, 36], "tokenizable": [286938, 20],
                        "retained_after_cap": [89600, 11]}:
        raise ValueError("M2 correction-ledger semantics drift")
    if (support.get("schema_version") != "msae_v3_support_v1"
            or support.get("status") != "eligible" or set(support.get("roles", {})) != set(base.ROLES)):
        raise ValueError("M2 support semantics drift")
    if any(set(support["roles"][role]) != set(base.TASKS)
           or any(support["roles"][role][task_name].get("status") != "eligible"
                  for task_name in base.TASKS) for role in base.ROLES):
        raise ValueError("M2 role/task support is incomplete")
    template_rows = templates.get("templates")
    if (templates.get("schema_version") != "msae_v3_prefix_templates_v1"
            or not isinstance(template_rows, list) or len(template_rows) != 4
            or [row.get("literal") for row in template_rows] != list(base.PREFIXES)
            or len({row.get("length") for row in template_rows}) != 4):
        raise ValueError("M2 prefix-template semantics drift")
    entries = maps.get("map_entries")
    if (maps.get("schema_version") != "msae_v3_bootstrap_maps_v1"
            or maps.get("draws_per_role_task") != 500 or not isinstance(entries, list)
            or len(entries) != len(base.ROLES) * len(base.TASKS) * 500):
        raise ValueError("M2 map registry dimensions drift")
    keys = {(row.get("role"), row.get("task"), row.get("draw")) for row in entries}
    expected_keys = {(role, task_name, draw) for role in base.ROLES
                     for task_name in base.TASKS for draw in range(500)}
    if keys != expected_keys or len(keys) != len(entries):
        raise ValueError("M2 map registry keys are incomplete or duplicated")
    finite = collections.Counter((row["role"], row["task"]) for row in entries
                                 if row.get("finite") is True and row.get("reasons") == [])
    if any(row.get("finite") not in {True, False}
           or base.HEX_RE.fullmatch(str(row.get("map_sha256"))) is None for row in entries):
        raise ValueError("M2 map entry type/digest drift")
    expected_matrix = {role: {task_name: finite[(role, task_name)] for task_name in base.TASKS}
                       for role in base.ROLES}
    if (matrix.get("schema_version") != "msae_v3_finite_pass_matrix_v1"
            or matrix.get("status") != "eligible" or matrix.get("minimum_finite_draws") != 490
            or matrix.get("finite_draw_counts") != expected_matrix
            or any(count != 500 for values in expected_matrix.values() for count in values.values())
            or matrix.get("map_payload_sha256") != base.sha_file(root / prefix / "maps.json")):
        raise ValueError("M2 finite-pass matrix does not close over maps")
    if imports.get("schema_version") != "msae_v3_protocol_imports_v1":
        raise ValueError("M2 protocol-import semantics drift")
    return {"label_rows": 1491748, "role_task_cells": 68, "map_entries": len(entries),
            "finite_draws_per_cell": 500, "support_status": "eligible",
            "finite_pass_status": "eligible", "correction_denominators": denominators}


@contextlib.contextmanager
def _later_data_projection() -> Iterable[None]:
    original = base._phase_data_names
    def names(phase: str) -> set[str]:
        result = original(phase)
        if phase in {"M1", "M2"}:
            result |= {name for name in base.V3_DATA_PHASE_FILES["M4"]
                       if (V3_DATA / name).exists()}
        return result
    base._phase_data_names = names
    try:
        yield
    finally:
        base._phase_data_names = original


def _m2_completion_payload() -> dict[str, Any]:
    with _later_data_projection():
        continuation.verify_m1_completion(M1_REVIEWED_COMPLETION_SHA256, allow_m2_recovery=True)
        base.verify_baseline_projection("M2")
    entries = [_regular_entry(V3_DATA / name) for name in base.V3_DATA_PHASE_FILES["M2"]]
    return {"schema_version": "msae_v3_m2_completion_manifest_v1", "protocol_id": PROTOCOL,
            "reviewed_m1_completion_sha256": M1_REVIEWED_COMPLETION_SHA256,
            "entries": entries, "entry_count": len(entries),
            "entries_sha256": base.sha_bytes(base.canonical_bytes(entries)),
            "success_semantics": _validate_m2_semantics(),
            "status": "m2_support_and_maps_eligible_ready_for_independent_review_pin"}


def build_m2_completion() -> dict[str, Any]:
    raise RuntimeError("gen3 cannot construct or replace the immutable M2 completion")


def verify_m2_completion(reviewed_sha256: str) -> dict[str, Any]:
    # Verifier ownership remains with the exact immutable gen2 runtime that
    # created and reviewed this completion. Gen3 may only consume its result.
    return predecessor_runtime.verify_m2_completion(reviewed_sha256)


def checkpoint_registry(*, root: Path = ROOT) -> list[dict[str, Any]]:
    specs = [
        ("g4", 42, "inc1e2", "final_step249244_tok1000000016.pt", "replicate"),
        ("g5", 43, "inc1e2", "final_step249244_tok1000000016.pt", "replicate"),
        ("g6", 44, "inc1e2", "final_step249675_tok1000000042.pt", "replicate"),
        ("g7", 42, "inc0", "final_step249244_tok1000000016.pt", "matched_negative_control"),
    ]
    rows: list[dict[str, Any]] = []
    for checkpoint_id, seed, suffix, filename, role in specs:
        run_id = f"k2_wave2_fast_{checkpoint_id}_L3_s{seed}_{suffix}"
        relative_root = (Path("pilot_runs/20260601_132158_k2_msae_wave2_fastdata_stream/outputs") /
                         run_id)
        checkpoint = root / relative_root / "checkpoints" / filename
        summary = root / relative_root / "train_summary.json"
        metrics = root / relative_root / "train_metrics.jsonl"
        payload = base.strict_json_loads(summary.read_text(encoding="utf-8"))
        if payload.get("seed") != seed or payload.get("layer_index") != 3:
            raise ValueError(f"checkpoint summary mismatch: {checkpoint_id}")
        rows.append({
            "checkpoint_id": checkpoint_id, "role": role, "seed": seed,
            "training_run_id": run_id,
            "checkpoint_path": (relative_root / "checkpoints" / filename).as_posix(),
            "checkpoint_size": checkpoint.stat().st_size,
            "checkpoint_sha256": base.sha_file(checkpoint),
            "summary_path": (relative_root / "train_summary.json").as_posix(),
            "summary_sha256": base.sha_file(summary),
            "metrics_path": (relative_root / "train_metrics.jsonl").as_posix(),
            "metrics_sha256": base.sha_file(metrics),
            "tokens_seen": payload["tokens_seen"], "lambda_inc": payload["lambda_inc"],
            "training_git_state": payload["git_commit_hash"],
        })
    if ([row["checkpoint_id"] for row in rows] != ["g4", "g5", "g6", "g7"]
            or [row["role"] for row in rows] != ["replicate", "replicate", "replicate", "matched_negative_control"]
            or len({row["seed"] for row in rows[:3]}) != 3
            or len({row["checkpoint_sha256"] for row in rows[:3]}) != 3
            or any(base.HEX_RE.fullmatch(row["checkpoint_sha256"]) is None for row in rows)):
        raise ValueError("checkpoint lineage registry does not meet the frozen design")
    if rows[3]["seed"] != rows[0]["seed"] or rows[3]["lambda_inc"] == rows[0]["lambda_inc"]:
        raise ValueError("g7 is not the frozen matched negative control")
    return rows


def _expected_endpoint_keys() -> set[tuple[Any, ...]]:
    """Independently enumerate the frozen endpoint product.

    This deliberately returns typed tuples rather than endpoint IDs so a bug in
    string formatting cannot make construction and validation agree.
    """
    keys: set[tuple[Any, ...]] = set()
    localization_metrics = ("recovery", "leakage", "selectivity")
    for role, checkpoints, components in (
        ("C1", ("raw",), ("raw_full", "simple_family_projection",
                          "simple_family_complement", "simple_family_residual")),
        ("C2", ("g4", "g5", "g6", "g7"),
         ("assigned", "nonassigned", "joint", "complement", "residual")),
    ):
        for checkpoint in checkpoints:
            for family, tasks in FAMILIES.items():
                for task_name in tasks:
                    for component in components:
                        for metric in localization_metrics:
                            keys.add(("localization", role, checkpoint, family,
                                      task_name, component, metric, 3))
    for family, tasks in FAMILIES.items():
        for task_name in tasks:
            for metric in localization_metrics:
                keys.add(("functional_reproducibility", "C2", ("g4", "g5", "g6"),
                          "g7_descriptive_only", family, "task", task_name, metric))
        for metric in localization_metrics:
            keys.add(("functional_reproducibility", "C2", ("g4", "g5", "g6"),
                      "g7_descriptive_only", family, "family_summary", None, metric))
    for role, checkpoints, components in (
        ("C1", ("raw",), ("raw_full", "simple_family_projection",
                            "simple_family_complement", "simple_family_residual")),
        ("C2", ("g4", "g5", "g6", "g7"),
         ("assigned", "nonassigned", "joint", "complement", "residual")),
    ):
        for checkpoint in checkpoints:
            for component in components:
                for task_name in TIER2:
                    for metric in ("recovery", "retention", "leakage"):
                        keys.add(("collateral", role, checkpoint, component, task_name, metric))
    for checkpoint in ("g4", "g5", "g6", "g7"):
        for transform in TRANSFORMS:
            for control in CONTROLS:
                keys.add(("counterfactual", "C2", checkpoint, transform, control))
    for role in base.ROLES:
        for baseline in BASELINES:
            keys.add(("baseline", role, baseline))
    return keys


def _endpoint_key(row: Mapping[str, Any]) -> tuple[Any, ...]:
    category = row.get("category")
    if category == "localization":
        return (category, row.get("role"), row.get("checkpoint"), row.get("family"),
                row.get("task"), row.get("component"), row.get("metric"), row.get("layer"))
    if category == "functional_reproducibility":
        checkpoints = row.get("checkpoints")
        return (category, row.get("role"), tuple(checkpoints) if isinstance(checkpoints, list) else None,
                row.get("control"), row.get("family"), row.get("summary_level"),
                row.get("task"), row.get("metric"))
    if category == "collateral":
        return (category, row.get("role"), row.get("checkpoint"), row.get("component"),
                row.get("task"), row.get("metric"))
    if category == "counterfactual":
        return (category, row.get("role"), row.get("checkpoint"), row.get("transform"), row.get("control"))
    if category == "baseline":
        return (category, row.get("role"), row.get("baseline"))
    raise ValueError(f"unknown endpoint category: {category!r}")


def validate_endpoint_registry(value: Mapping[str, Any]) -> dict[str, Any]:
    entries = value.get("entries")
    if not isinstance(entries, list):
        raise ValueError("endpoint entries are not an array")
    keys = [_endpoint_key(row) for row in entries]
    expected = _expected_endpoint_keys()
    if len(keys) != len(set(keys)) or set(keys) != expected:
        missing = expected - set(keys)
        extra = set(keys) - expected
        raise ValueError(f"endpoint product mismatch: missing={len(missing)} extra={len(extra)}")
    ids = [row.get("endpoint_id") for row in entries]
    if any(not isinstance(item, str) or not item for item in ids) or len(ids) != len(set(ids)):
        raise ValueError("endpoint IDs are missing or duplicated")
    def expected_id(key: tuple[Any, ...]) -> str:
        category = key[0]
        if category == "localization":
            _, role, checkpoint, family, task, component, metric, layer = key
            return f"{role}.{checkpoint}.{family}.{task}.{component}.{metric}.L{layer}"
        if category == "functional_reproducibility":
            _, _, checkpoints, _, family, level, task, metric = key
            unit = task if level == "task" else "family_summary"
            return f"{'_'.join(checkpoints)}.{family}.{unit}.{metric}.spread"
        if category == "collateral":
            _, role, checkpoint, component, task, metric = key
            return f"{role}.{checkpoint}.{component}.{task}.{metric}.L3"
        if category == "counterfactual":
            _, role, checkpoint, transform, control = key
            return f"{role}.{checkpoint}.{transform}.{control}.L3"
        _, role, baseline = key
        return f"{role}.{baseline}.registered"
    if any(row["endpoint_id"] != expected_id(key) for row, key in zip(entries, keys)):
        raise ValueError("endpoint ID is not the canonical typed-key encoding")
    for row in entries:
        required = (["maximum_spread", "uncertainty", "status"]
                    if row["category"] == "functional_reproducibility"
                    else ["estimate", "uncertainty", "status"]
                    if row["category"] == "collateral" else None)
        if required is not None and row.get("required_output_fields") != required:
            raise ValueError("endpoint required-output schema mismatch")
    counts = collections.Counter(row["category"] for row in entries)
    expected_counts = collections.Counter(key[0] for key in expected)
    if (value.get("schema_version") != "msae_v3_endpoint_registry_v2"
            or value.get("protocol_id") != PROTOCOL
            or value.get("endpoint_count") != len(expected)
            or value.get("category_counts") != dict(expected_counts)
            or value.get("endpoint_id_set_sha256") !=
               base.sha_bytes(base.canonical_bytes(sorted(ids)))):
        raise ValueError("endpoint registry summary mismatch")
    if (value.get("families") != {key: list(rows) for key, rows in FAMILIES.items()}
            or value.get("tier2_tasks") != list(TIER2)
            or value.get("counterfactual_transforms") != list(TRANSFORMS)
            or value.get("counterfactual_controls") != list(CONTROLS)
            or value.get("baselines") != list(BASELINES)
            or value.get("g7_interpretation") != "matched_negative_control_not_replicate"
            or value.get("C1_scope") != "raw_simple_G1_operands_only"
            or value.get("C2_scope") != "G2_and_descriptive_control"):
        raise ValueError("endpoint registry metadata mismatch")
    return dict(value)


def endpoint_registry() -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for role in ("C1", "C2"):
        checkpoints = ("raw",) if role == "C1" else ("g4", "g5", "g6", "g7")
        components = ("raw_full", "simple_family_projection", "simple_family_complement", "simple_family_residual") if role == "C1" else ("assigned", "nonassigned", "joint", "complement", "residual")
        for checkpoint in checkpoints:
            for family, tasks in FAMILIES.items():
                for task_name in tasks:
                    for component in components:
                        for metric in ("recovery", "leakage", "selectivity"):
                            entries.append({"category": "localization", "role": role,
                                            "checkpoint": checkpoint, "family": family,
                                            "task": task_name, "component": component,
                                            "metric": metric, "layer": 3,
                                            "endpoint_id": f"{role}.{checkpoint}.{family}.{task_name}.{component}.{metric}.L3"})
    for family, tasks in FAMILIES.items():
        for task_name in tasks:
            for metric in ("recovery", "leakage", "selectivity"):
                entries.append({"category": "functional_reproducibility", "role": "C2",
                                "checkpoints": ["g4", "g5", "g6"], "control": "g7_descriptive_only",
                                "family": family, "summary_level": "task", "task": task_name,
                                "metric": metric,
                                "required_output_fields": ["maximum_spread", "uncertainty", "status"],
                                "endpoint_id": f"g4_g5_g6.{family}.{task_name}.{metric}.spread"})
        for metric in ("recovery", "leakage", "selectivity"):
            entries.append({"category": "functional_reproducibility", "role": "C2",
                            "checkpoints": ["g4", "g5", "g6"], "control": "g7_descriptive_only",
                            "family": family, "summary_level": "family_summary", "task": None,
                            "metric": metric,
                            "required_output_fields": ["maximum_spread", "uncertainty", "status"],
                            "endpoint_id": f"g4_g5_g6.{family}.family_summary.{metric}.spread"})
    for role in ("C1", "C2"):
        checkpoints = ("raw",) if role == "C1" else ("g4", "g5", "g6", "g7")
        components = (("raw_full", "simple_family_projection", "simple_family_complement",
                       "simple_family_residual") if role == "C1"
                      else ("assigned", "nonassigned", "joint", "complement", "residual"))
        for checkpoint in checkpoints:
            for component in components:
                for task_name in TIER2:
                    for metric in ("recovery", "retention", "leakage"):
                        entries.append({"category": "collateral", "role": role,
                                        "checkpoint": checkpoint, "component": component,
                                        "task": task_name, "metric": metric,
                                        "required_output_fields": ["estimate", "uncertainty", "status"],
                                        "endpoint_id": f"{role}.{checkpoint}.{component}.{task_name}.{metric}.L3"})
    for checkpoint in ("g4", "g5", "g6", "g7"):
        for transform in TRANSFORMS:
            for control in CONTROLS:
                entries.append({"category": "counterfactual", "role": "C2",
                                "checkpoint": checkpoint, "transform": transform, "control": control,
                                "endpoint_id": f"C2.{checkpoint}.{transform}.{control}.L3"})
    for role in base.ROLES:
        for baseline in BASELINES:
            entries.append({"category": "baseline", "role": role, "baseline": baseline,
                            "endpoint_id": f"{role}.{baseline}.registered"})
    ids = [row["endpoint_id"] for row in entries]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate endpoint IDs")
    counts = collections.Counter(row["category"] for row in entries)
    value = {"schema_version": "msae_v3_endpoint_registry_v2", "protocol_id": PROTOCOL,
            "entries": entries, "endpoint_count": len(entries), "category_counts": dict(counts),
            "endpoint_id_set_sha256": base.sha_bytes(base.canonical_bytes(sorted(ids))),
            "families": {key: list(value) for key, value in FAMILIES.items()},
            "tier2_tasks": list(TIER2), "counterfactual_transforms": list(TRANSFORMS),
            "counterfactual_controls": list(CONTROLS), "baselines": list(BASELINES),
            "g7_interpretation": "matched_negative_control_not_replicate",
            "C1_scope": "raw_simple_G1_operands_only", "C2_scope": "G2_and_descriptive_control"}
    validate_endpoint_registry(value)
    return value


def _canonical_review(
    path: Path,
    supplied_sha256: str,
    *,
    scope: str,
    expected_digests: Mapping[str, str],
) -> dict[str, Any]:
    """Validate one create-once review and its exact machine control lines."""
    base.validate_sha256(supplied_sha256, f"{scope} review SHA-256")
    raw = _regular_bytes(path, mode=0o644)
    if base.sha_bytes(raw) != supplied_sha256 or not raw.endswith(b"\n") or b"\r" in raw:
        raise ValueError(f"{scope} review digest/newline drift")
    text = raw.decode("utf-8", errors="strict")
    if text.encode("utf-8") != raw:
        raise ValueError(f"{scope} review is not canonical UTF-8")
    lines = text.splitlines()
    stripped = [line.strip() for line in lines]
    for raw_line, stripped_line in zip(lines, stripped):
        control_like = (re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", stripped_line,
                                 re.ASCII) is not None
                        or re.match(r"[A-Z][A-Z0-9_]*_SHA256\b", stripped_line,
                                    re.ASCII) is not None)
        if control_like and raw_line != stripped_line:
            raise ValueError(f"{scope} review has indented/padded control lines")
    malformed_review_controls = [line for line in lines
        if re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", line, re.ASCII)
        and line not in {"VERDICT: SHIP", f"REVIEW_SCOPE: {scope}"}]
    if malformed_review_controls:
        raise ValueError(f"{scope} review has malformed/conflicting controls")
    verdicts = [line for line in lines if line.startswith("VERDICT:")]
    scopes = [line for line in lines if line.startswith("REVIEW_SCOPE:")]
    if verdicts != ["VERDICT: SHIP"] or scopes != [f"REVIEW_SCOPE: {scope}"]:
        raise ValueError(f"{scope} review verdict/scope is not uniquely SHIP")
    digest_rows: dict[str, str] = {}
    malformed_digest_controls = [line for line in lines
        if re.match(r"[A-Z][A-Z0-9_]*_SHA256\b", line, re.ASCII)
        and re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}", line,
                         re.ASCII) is None]
    if malformed_digest_controls:
        raise ValueError(f"{scope} review has malformed digest controls")
    digest_lines = [line for line in lines
                    if re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}",
                                    line, re.ASCII)]
    for line in digest_lines:
        match = re.fullmatch(r"([A-Z][A-Z0-9_]*)_SHA256: ([0-9a-f]{64})", line,
                             re.ASCII)
        if match is None or match.group(1) in digest_rows:
            raise ValueError(f"{scope} review has malformed/duplicate digest controls")
        digest_rows[match.group(1)] = match.group(2)
    if digest_rows != dict(expected_digests):
        raise ValueError(f"{scope} review digest controls mismatch: {digest_rows!r}")
    expected_control_lines = [
        "VERDICT: SHIP", f"REVIEW_SCOPE: {scope}",
        *(f"{key}_SHA256: {value}" for key, value in expected_digests.items()),
    ]
    observed_control_lines = [line for line in lines if (
        re.fullmatch(r"VERDICT: SHIP", line, re.ASCII)
        or re.fullmatch(rf"REVIEW_SCOPE: {re.escape(scope)}", line, re.ASCII)
        or re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}",
                        line, re.ASCII))]
    if observed_control_lines != expected_control_lines:
        raise ValueError(f"{scope} review control order drift")
    return {
        "path": path.relative_to(ROOT).as_posix(),
        "sha256": supplied_sha256,
        "scope": scope,
        "digests": digest_rows,
        "entry": _regular_entry(path),
    }


def _plan_review_binding(supplied_sha256: str) -> dict[str, Any]:
    if base.sha_file(PLAN_PATH) != FROZEN_PLAN_SHA256:
        raise ValueError("frozen gen5 plan bytes drifted")
    if supplied_sha256 != FROZEN_PLAN_REVIEW_SHA256:
        raise ValueError("setup does not name the reviewed frozen plan transcript")
    return _canonical_review(
        PLAN_REVIEW,
        supplied_sha256,
        scope="gen5_plan",
        expected_digests={
            "FAILED_GEN4_PLAN": FAILED_GEN4_PLAN_SHA256,
            "FAILED_GEN4_PLAN_REVIEW": FAILED_GEN4_PLAN_REVIEW_SHA256,
            "GEN5_PLAN": FROZEN_PLAN_SHA256,
        },
    )


def _current_gen5_entries() -> dict[str, dict[str, Any]]:
    paths = {
        "GEN5_PLAN": PLAN_PATH, "GEN5_PLAN_REVIEW": PLAN_REVIEW,
        "GEN5_CONTROLLER": continuation.CONTROLLER_PATH, "GEN5_RUNTIME": RUNTIME,
        "GEN5_RUNNER": RUNNER, "GEN5_LAUNCHER": LAUNCHER,
        "GEN5_TMUX_TEST_SUPERVISOR": TMUX_TEST_SUPERVISOR,
        "GEN5_RFC": RUNTIME_RFC, "GEN5_TESTS": RUNTIME_TEST,
    }
    return {name: _regular_entry(path) for name, path in paths.items()}


def _failed_gen4_entries() -> dict[str, dict[str, Any]]:
    paths = {
        "FAILED_GEN4_PLAN": FAILED_GEN4_PLAN,
        "FAILED_GEN4_PLAN_REVIEW": FAILED_GEN4_PLAN_REVIEW,
        "FAILED_GEN4_CONTROLLER": ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen4.py",
        "FAILED_GEN4_RUNTIME": ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen4_runtime.py",
        "FAILED_GEN4_RUNNER": ROOT / "scripts/run_msae_independent_calibration_v3_gen4.py",
        "FAILED_GEN4_LAUNCHER": ROOT / "scripts/launch_msae_independent_calibration_v3_gen4.sh",
        "FAILED_GEN4_RFC": ROOT / "docs/rfc-msae-independent-measurement-v3-post-m4-gen4.md",
        "FAILED_GEN4_TESTS": ROOT / "tests/test_msae_independent_measurement_v3_post_m4_gen4.py",
    }
    expected = {
        "FAILED_GEN4_PLAN": FAILED_GEN4_PLAN_SHA256,
        "FAILED_GEN4_PLAN_REVIEW": FAILED_GEN4_PLAN_REVIEW_SHA256,
        "FAILED_GEN4_CONTROLLER": FAILED_GEN4_CONTROLLER_SHA256,
        "FAILED_GEN4_RUNTIME": FAILED_GEN4_RUNTIME_SHA256,
        "FAILED_GEN4_RUNNER": FAILED_GEN4_RUNNER_SHA256,
        "FAILED_GEN4_LAUNCHER": FAILED_GEN4_LAUNCHER_SHA256,
        "FAILED_GEN4_RFC": FAILED_GEN4_RFC_SHA256,
        "FAILED_GEN4_TESTS": FAILED_GEN4_TESTS_SHA256,
    }
    entries = {name: _regular_entry(path) for name, path in paths.items()}
    if {name: row["sha256"] for name, row in entries.items()} != expected:
        raise ValueError("immutable failed-gen4 subject drift")
    return entries


def _renameat2_noreplace_probe(source: Path, destination: Path) -> int:
    libc = ctypes.CDLL(None, use_errno=True)
    function = getattr(libc, "renameat2", None)
    if function is None:
        return errno.ENOSYS
    function.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                         ctypes.c_char_p, ctypes.c_uint]
    function.restype = ctypes.c_int
    if function(-100, os.fsencode(source), -100, os.fsencode(destination), 1) == 0:
        return 0
    return ctypes.get_errno()


def _validate_capability_report(value: Mapping[str, Any]) -> None:
    required = {
        "schema_version", "protocol_id", "writer_generation", "argv", "cwd",
        "started_utc", "ended_utc", "failed_gen4_runtime_entry", "errno",
        "error_name", "filesystem", "probe_root", "source", "destination",
        "before", "after", "transcript_utf8", "transcript_sha256",
        "protocol_path_used", "model_gpu_tmux", "gen5_subject",
    }
    if (set(value) != required
            or value.get("schema_version") != "msae_v3_gen5_gen4_capability_reproduction_v1"
            or value.get("protocol_id") != PROTOCOL
            or value.get("writer_generation") != GENERATION
            or value.get("errno") != errno.EINVAL
            or value.get("error_name") != "EINVAL"
            or value.get("probe_root") != str(CAPABILITY_PROBE_ROOT)
            or value.get("protocol_path_used") is not False
            or value.get("model_gpu_tmux") is not False
            or value.get("cwd") != str(ROOT)):
        raise ValueError("gen4 capability report semantic drift")
    timestamp_pattern = r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z"
    if (re.fullmatch(timestamp_pattern, str(value.get("started_utc")), re.ASCII) is None
            or re.fullmatch(timestamp_pattern, str(value.get("ended_utc")), re.ASCII) is None
            or str(value["ended_utc"]) < str(value["started_utc"])):
        raise ValueError("gen4 capability UTC timestamp drift")
    transcript = str(value.get("transcript_utf8")).encode("utf-8")
    if value.get("transcript_sha256") != base.sha_bytes(transcript):
        raise ValueError("gen4 capability transcript digest drift")
    failed = value.get("failed_gen4_runtime_entry")
    if not isinstance(failed, dict) or failed.get("sha256") != FAILED_GEN4_RUNTIME_SHA256:
        raise ValueError("gen4 capability runtime binding drift")
    filesystem = value.get("filesystem")
    if (not isinstance(filesystem, dict)
            or filesystem.get("filesystem_magic") != "0x6969"
            or filesystem.get("mountinfo", {}).get("filesystem_type") not in {"nfs", "nfs4"}):
        raise ValueError("gen4 capability filesystem binding drift")
    if value.get("gen5_subject") != _current_gen5_entries():
        raise ValueError("gen4 capability gen5 subject drift")


def _perform_gen4_capability_probe(started: int) -> dict[str, Any]:
    if _path_present(CAPABILITY_PROBE_ROOT):
        raise ValueError("capability probe root is not initially absent")
    CAPABILITY_PROBE_ROOT.mkdir(mode=0o700)
    os.chmod(CAPABILITY_PROBE_ROOT, 0o700)
    base._fsync_directory(CAPABILITY_PROBE_ROOT.parent)
    source = CAPABILITY_PROBE_ROOT / "gen4_staging.json"
    destination = CAPABILITY_PROBE_ROOT / "gen4_destination.json"
    raw = base.canonical_bytes({"schema_version": "msae_v3_gen4_publisher_probe_v1"})
    fd = os.open(source, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        os.fchmod(fd, 0o600); _write_all(fd, raw); os.fsync(fd)
    finally:
        os.close(fd)
    base._fsync_directory(CAPABILITY_PROBE_ROOT)
    before_st = source.lstat()
    before = {"source": _lstat_binding(source), "destination_absent": not _path_present(destination)}
    error = _renameat2_noreplace_probe(source, destination)
    after_st = source.lstat()
    after = {"source": _lstat_binding(source), "destination_absent": not _path_present(destination)}
    if (error != errno.EINVAL or _path_present(destination)
            or _regular_bytes(source, mode=0o600) != raw
            or (before_st.st_dev, before_st.st_ino, before_st.st_size) !=
               (after_st.st_dev, after_st.st_ino, after_st.st_size)):
        raise ValueError("gen4 capability reproduction did not reproduce EINVAL safely")
    mount = _mount_identity(CAPABILITY_PROBE_ROOT)
    transcript = ("renameat2(RENAME_NOREPLACE)\n"
                  f"source={source.name}\ndestination={destination.name}\n"
                  "return=-1\nerrno=22 EINVAL\n")
    source.unlink(); base._fsync_directory(CAPABILITY_PROBE_ROOT)
    CAPABILITY_PROBE_ROOT.rmdir(); base._fsync_directory(CAPABILITY_PROBE_ROOT.parent)
    ended = int(time.time())
    utc = lambda value: time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(value))
    value = {
        "schema_version": "msae_v3_gen5_gen4_capability_reproduction_v1",
        "protocol_id": PROTOCOL, "writer_generation": GENERATION,
        "argv": [".venv-atlas/bin/python", "-S", "-B", "-I",
                 "scripts/msae_independent_measurement_v3_post_m2_gen5.py",
                 "probe-gen4-publisher-capability", "--output",
                 CAPABILITY_REPORT.relative_to(ROOT).as_posix()],
        "cwd": str(ROOT), "started_utc": utc(started), "ended_utc": utc(ended),
        "failed_gen4_runtime_entry": _failed_gen4_entries()["FAILED_GEN4_RUNTIME"],
        "errno": error, "error_name": "EINVAL", "filesystem": mount,
        "probe_root": str(CAPABILITY_PROBE_ROOT),
        "source": {"basename": source.name, "mode": 0o600},
        "destination": {"basename": destination.name, "mode": 0o600},
        "before": before, "after": after, "transcript_utf8": transcript,
        "transcript_sha256": base.sha_bytes(transcript.encode("utf-8")),
        "protocol_path_used": False, "model_gpu_tmux": False,
        "gen5_subject": _current_gen5_entries(),
    }
    _validate_capability_report(value)
    return value


def probe_gen4_publisher_capability(output: Path) -> dict[str, Any]:
    if Path(output) != CAPABILITY_REPORT:
        raise ValueError("capability report output path drift")
    _plan_review_binding(FROZEN_PLAN_REVIEW_SHA256)
    _failed_gen4_entries()
    if _path_present(CAPABILITY_REPORT) and not _path_present(CAPABILITY_TRANSACTION):
        _exact_directory_entries(
            CAPABILITY_ANALYSIS_ROOT, {CAPABILITY_REPORT.name}, mode=0o700)
        raw = _regular_bytes(CAPABILITY_REPORT, mode=0o644)
        value = base.strict_json_loads(raw.decode("utf-8"))
        if raw != base.canonical_bytes(value):
            raise ValueError("capability report canonical bytes drift")
        _validate_capability_report(value)
        return value
    if not _path_present(CAPABILITY_ANALYSIS_ROOT):
        if not _path_present(CAPABILITY_ANALYSIS_ROOT.parent):
            _ensure_secure_dir(CAPABILITY_ANALYSIS_ROOT.parent)
        _ensure_secure_dir(CAPABILITY_ANALYSIS_ROOT)
    allowed = {CAPABILITY_TRANSACTION.name} | (
        {CAPABILITY_REPORT.name} if _path_present(CAPABILITY_REPORT) else set())
    _exact_directory_entries(CAPABILITY_ANALYSIS_ROOT, allowed, mode=0o700)
    if not _path_present(CAPABILITY_TRANSACTION):
        _ensure_secure_dir(CAPABILITY_TRANSACTION)
    observed_transaction_children = {
        entry.name for entry in os.scandir(CAPABILITY_TRANSACTION)}
    permitted_transaction_children = {
        "transaction.json", ".transaction.json.bootstrap", "report.payload",
        *(f".transaction.json.attempt-{index}" for index in range(1, 4)),
        *(f".{CAPABILITY_REPORT.name}.attempt-{index}" for index in range(1, 4)),
    }
    if not observed_transaction_children <= permitted_transaction_children:
        raise ValueError("capability transaction has an undeclared child")
    _exact_directory_entries(
        CAPABILITY_TRANSACTION, observed_transaction_children, mode=0o700)
    descriptor_path = CAPABILITY_TRANSACTION / "transaction.json"
    bootstrap_path = CAPABILITY_TRANSACTION / ".transaction.json.bootstrap"
    if (not _path_present(descriptor_path) and not _path_present(bootstrap_path)
            and observed_transaction_children):
        raise ValueError("capability transaction lost descriptor authority")
    if _path_present(descriptor_path) or _path_present(bootstrap_path):
        authority_path = descriptor_path if _path_present(descriptor_path) else bootstrap_path
        descriptor_raw = _regular_bytes(authority_path, mode=0o600)
        descriptor = base.strict_json_loads(descriptor_raw.decode("utf-8"))
        if descriptor_raw != base.canonical_bytes(descriptor):
            raise ValueError("capability transaction descriptor drift")
        sealed = descriptor.get("sealed_random_payloads", {}).get("report_b64")
        if not isinstance(sealed, str):
            raise ValueError("capability transaction sealed report missing")
        report_raw = base64.b64decode(sealed, validate=True)
        report = base.strict_json_loads(report_raw.decode("utf-8"))
        _validate_capability_report(report)
    else:
        report = _perform_gen4_capability_probe(int(time.time()))
        report_raw = base.canonical_bytes(report)
        row = _publication_row(
            0, CAPABILITY_TRANSACTION, "report.payload",
            CAPABILITY_ANALYSIS_ROOT, CAPABILITY_REPORT.name,
            report_raw, 0o644, "gen4_capability_report")
        authority = base.sha_bytes(base.canonical_bytes({
            "plan_review_sha256": FROZEN_PLAN_REVIEW_SHA256,
            "gen5_subject": _current_gen5_entries(),
        }))
        descriptor = _link_transaction_payload(
            kind="capability", authority_sha256=authority, publications=[row],
            maximum_seconds=300,
            sealed_random_payloads={"report_b64": base64.b64encode(report_raw).decode("ascii")})
    row = _publication_row(
        0, CAPABILITY_TRANSACTION, "report.payload",
        CAPABILITY_ANALYSIS_ROOT, CAPABILITY_REPORT.name,
        report_raw, 0o644, "gen4_capability_report")
    authority = base.sha_bytes(base.canonical_bytes({
        "plan_review_sha256": FROZEN_PLAN_REVIEW_SHA256,
        "gen5_subject": _current_gen5_entries(),
    }))
    _validate_link_transaction_descriptor(
        descriptor, kind="capability", authority_sha256=authority,
        publications=[row], maximum_seconds=300)
    if descriptor["sealed_random_payloads"] != {
            "report_b64": base64.b64encode(report_raw).decode("ascii")}:
        raise ValueError("capability transaction sealed report drift")
    _bootstrap_link_transaction(CAPABILITY_TRANSACTION, descriptor)
    _link_publication(descriptor, row, report_raw, descriptor_path=descriptor_path)
    # Re-establish the complete outer and inner authority projections after
    # publication and immediately before deleting the recovery descriptor.
    # A callback/concurrent mutation may not consume the one-way cleanup door.
    _exact_directory_entries(
        CAPABILITY_ANALYSIS_ROOT,
        {CAPABILITY_REPORT.name, CAPABILITY_TRANSACTION.name}, mode=0o700)
    _exact_directory_entries(
        CAPABILITY_TRANSACTION, {descriptor_path.name}, mode=0o700)
    report_before = CAPABILITY_REPORT.lstat()
    checked_report_raw = _regular_bytes(CAPABILITY_REPORT, mode=0o644)
    report_after = CAPABILITY_REPORT.lstat()
    report_identity = lambda item: (
        item.st_dev, item.st_ino, item.st_mode, item.st_uid, item.st_nlink,
        item.st_size, item.st_mtime_ns, item.st_ctime_ns)
    if (checked_report_raw != report_raw
            or report_identity(report_before) != report_identity(report_after)):
        raise ValueError("capability report changed before authority cleanup")
    checked_descriptor_raw = _regular_bytes(descriptor_path, mode=0o600)
    if checked_descriptor_raw != base.canonical_bytes(descriptor):
        raise ValueError("capability descriptor changed before authority cleanup")
    _validate_capability_report(base.strict_json_loads(
        checked_report_raw.decode("utf-8")))
    if _path_present(descriptor_path):
        descriptor_path.unlink(); base._fsync_directory(CAPABILITY_TRANSACTION)
    if any(os.scandir(CAPABILITY_TRANSACTION)):
        raise ValueError("capability transaction cleanup drift")
    CAPABILITY_TRANSACTION.rmdir(); base._fsync_directory(CAPABILITY_ANALYSIS_ROOT)
    _validate_capability_report(report)
    return report


def _failed_gen3_entries() -> dict[str, dict[str, Any]]:
    paths = {
        "FAILED_GEN3_PLAN": FAILED_GEN3_PLAN,
        "FAILED_GEN3_PLAN_REVIEW": FAILED_GEN3_PLAN_REVIEW,
        "FAILED_GEN3_CONTROLLER": ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
        "FAILED_GEN3_RUNTIME": ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
        "FAILED_GEN3_RUNNER": ROOT / "scripts/run_msae_independent_calibration_v3_gen3.py",
        "FAILED_GEN3_LAUNCHER": ROOT / "scripts/launch_msae_independent_calibration_v3_gen3.sh",
        "FAILED_GEN3_RFC": ROOT / "docs/rfc-msae-independent-measurement-v3-post-m4-gen3.md",
        "FAILED_GEN3_TESTS": ROOT / "tests/test_msae_independent_measurement_v3_post_m4_gen3.py",
        "FAILED_GEN3_IMPLEMENTATION_REVIEW": FAILED_GEN3_IMPLEMENTATION_REVIEW,
    }
    entries = {name: _regular_entry(path) for name, path in paths.items()}
    expected = {
        "FAILED_GEN3_PLAN": FAILED_GEN3_PLAN_SHA256,
        "FAILED_GEN3_PLAN_REVIEW": FAILED_GEN3_PLAN_REVIEW_SHA256,
        "FAILED_GEN3_CONTROLLER": "734e52a4d5836b3084a887c3eb681d6842750ed471b817cf4c5b201260866cd5",
        "FAILED_GEN3_RUNTIME": "1fe6146984ba1faac59d95063cc6468e5be477f340cf17a43a66905f87a15d0f",
        "FAILED_GEN3_RUNNER": "d243b62dc081d32a59491837c40356b138b26e08e36eb294d2fb6ba0ac8073d6",
        "FAILED_GEN3_LAUNCHER": "6a036d17fac6fa60884c54c7d9f98bc45f2d9f2194d2b3beca1d85fa58b91ba1",
        "FAILED_GEN3_RFC": "3d879bf957b859e25feacb26fa25a20a0abba850e502c50a893b2b3408d118df",
        "FAILED_GEN3_TESTS": "04c32b11d7206927f2c4b33471f2c86d4eb47e954d4101d40d15f2c4094d4c2d",
        "FAILED_GEN3_IMPLEMENTATION_REVIEW": FAILED_GEN3_IMPLEMENTATION_REVIEW_SHA256,
    }
    observed = {name: entry["sha256"] for name, entry in entries.items()}
    if observed != expected:
        raise ValueError(f"immutable failed-gen3 entry drift: {observed!r}")
    return entries


def _verify_historical_preflight_readonly() -> dict[str, Any]:
    raw = _regular_bytes(PREFLIGHT_FAILURE_PATH, mode=0o644)
    if base.sha_bytes(raw) != HISTORICAL_PREFLIGHT_SHA256:
        raise ValueError("historical preflight digest drift")
    value = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(value):
        raise ValueError("historical preflight canonical bytes drift")
    expected_top = {
        "schema_version", "protocol_id", "generation", "status",
        "reviewed_m2_completion_sha256", "config_entry", "commitment_entry",
        "public_key_entry", "private_key_lstat", "bound_runtime_sha256",
        "failure", "stage_a", "authorization_signature", "model_gpu_tmux",
        "successor_generation",
    }
    if (set(value) != expected_top
            or value.get("generation") != "post_m2_gen1_failed_preflight"
            or value.get("successor_generation") != "post_m2_gen2"
            or value.get("stage_a") != "not_run"
            or value.get("authorization_signature") != "not_created"
            or value.get("model_gpu_tmux") != "not_run"):
        raise ValueError("historical preflight semantics drift")
    for key, expected_path, expected_sha in (
        ("config_entry", V3_CONFIG / "protocol.json", FAILED_M3_CONFIG_SHA256),
        ("commitment_entry", V3_CONFIG / "authorization_commitment.json", FAILED_M3_COMMITMENT_SHA256),
        ("public_key_entry", V3_CONFIG / "ed25519_public.pem", FAILED_M3_PUBLIC_SHA256),
    ):
        entry = value[key]
        current = _regular_entry(expected_path)
        historical_projection = {key: current[key] for key in (
            "path", "type", "mode", "size", "sha256", "verification_action")}
        if (entry.get("path") != expected_path.relative_to(ROOT).as_posix()
                or entry.get("sha256") != expected_sha
                or historical_projection != entry):
            raise ValueError(f"historical preflight {key} drift")
    private = value["private_key_lstat"]
    private_path = Path(private["path"])
    st = private_path.lstat()
    observed = {"path": str(private_path), "device": st.st_dev, "inode": st.st_ino,
                "uid": st.st_uid, "mode": stat.S_IMODE(st.st_mode),
                "size": st.st_size, "nlink": st.st_nlink, "content_read": False}
    if private != observed:
        raise ValueError("historical preflight private-key lstat drift")
    return value


def _gen3_control_flow_reproduction() -> dict[str, Any]:
    runtime_path = ROOT / "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py"
    source = runtime_path.read_text(encoding="utf-8")
    tree = ast.parse(source, filename=str(runtime_path))
    generation = None
    function = None
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(
                isinstance(target, ast.Name) and target.id == "GENERATION"
                for target in node.targets):
            if isinstance(node.value, ast.Constant):
                generation = node.value.value
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == "preserve_m3_preflight":
            function = node
    if generation != "post_m2_gen3" or function is None:
        raise ValueError("failed-gen3 control-flow source drift")
    raise_lines: list[int] = []
    write_lines: list[int] = []
    for node in ast.walk(function):
        if isinstance(node, ast.Raise) and isinstance(node.exc, ast.Call):
            args = node.exc.args
            if args and isinstance(args[0], ast.Constant) and args[0].value == "failed-preflight manifest drift":
                raise_lines.append(node.lineno)
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                and node.func.attr in {"write_once", "install_json"}):
            write_lines.append(node.lineno)
    if raise_lines != [3315] or write_lines != [3317] or raise_lines[0] >= write_lines[0]:
        raise ValueError("failed-gen3 dominating-raise proof drift")
    preflight = _verify_historical_preflight_readonly()
    return {
        "method": "exact_ast_and_immutable_preflight_reproduction",
        "runtime_sha256": base.sha_file(runtime_path),
        "runtime_generation": generation,
        "historical_successor_generation": preflight["successor_generation"],
        "mismatch": {"reconstructed": generation, "stored": preflight["successor_generation"]},
        "dominating_raise_line": raise_lines[0],
        "first_protocol_write_line": write_lines[0],
        "raise_dominates_first_protocol_write": True,
    }


def _gen3_terminal_payload(*, allow_setup_prefix: bool = False) -> dict[str, Any]:
    failed_entries = _failed_gen3_entries()
    trace_raw = GEN3_INVOCATION_2_TRACE.encode("utf-8")
    if len(trace_raw) != 935 or base.sha_bytes(trace_raw) != "e39e1583d30ce5eb0aa5277ff88d3eb37bee2eb357d8e68ca366591847413020":
        raise AssertionError("embedded gen3 invocation-2 traceback drift")
    current_entries = _current_gen5_entries()
    absent = [
        ROOT / "configs/msae_independent_measurement_v3_post_m2_gen3",
        FAILED_GEN3_PROV,
        ROOT / "data/msae_independent_measurement_v3_post_m2_gen3",
        Path("/jumbo/lisp/f004ndc/.msae_keys/independent_measurement_v3_post_m2_gen3_ed25519_private.pem"),
        Path("/jumbo/lisp/f004ndc/.msae_state/independent_measurement_v3_post_m2_gen3"),
        ROOT / "pilot_runs/20260821_msae_independent_measurement_v3_post_m2_gen3_calibration",
        Path("/tmp/msae_independent_measurement_v3_post_m2_gen3_primary"),
        Path("/tmp/msae_independent_measurement_v3_post_m2_gen3_rebuild"),
        GEN2_FAILURE_PATH,
    ]
    allowed_prefix_paths = {FAILED_GEN3_PROV, GEN2_FAILURE_PATH} if allow_setup_prefix else set()
    for path in absent:
        if _path_present(path) and path not in allowed_prefix_paths:
            raise ValueError(f"failed-gen3 current-absence drift: {path}")
    if allow_setup_prefix and _path_present(FAILED_GEN3_PROV):
        _exact_directory_entries(
            FAILED_GEN3_PROV,
            {GEN3_TERMINAL_PATH.name} if _path_present(GEN3_TERMINAL_PATH) else set(),
            mode=0o700,
        )
    derived = []
    for pattern in (
        "msae_independent_measurement_v3_post_m2_gen3_*.prescore.check.json",
        "msae_independent_measurement_v3_post_m2_gen3_*.prescore.trace.log",
        "msae_independent_measurement_v3_post_m2_gen3_*.sock",
    ):
        matches = sorted(str(path) for path in Path("/tmp").glob(pattern))
        if matches:
            raise ValueError(f"failed-gen3 derived-state drift: {matches}")
        derived.append({"pattern": f"/tmp/{pattern}", "matches": []})
    quarantine = []
    for relative in sorted(base.QUARANTINED):
        path = ROOT / relative
        st = path.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or stat.S_IMODE(st.st_mode) != 0o600 or st.st_nlink != 1):
            raise ValueError(f"quarantined lstat drift: {relative}")
        quarantine.append({"path": relative, "device": st.st_dev, "inode": st.st_ino,
                           "uid": st.st_uid, "mode": stat.S_IMODE(st.st_mode),
                           "size": st.st_size, "nlink": st.st_nlink,
                           "content_read": False})
    return {
        "schema_version": "msae_v3_gen3_setup_terminal_v1",
        "protocol_id": PROTOCOL,
        "generation": "post_m2_gen3",
        "writer_generation": GENERATION,
        "status": "failed_before_first_protocol_state_write",
        "setup_m3_command_attempts": 2,
        "setup_m3_attempt_statuses": ["failed_prewrite", "failed_prewrite"],
        "m3_protocol_state": "not_created",
        "stage_a": "not_run", "authorization": "not_run",
        "model": "not_run", "job": "not_run", "tmux": "not_run",
        "successor_generation": GENERATION,
        "operator_disclosed": {
            "argv": list(GEN3_SETUP_ARGV), "argv_sha256": base.sha_bytes(base.canonical_bytes(list(GEN3_SETUP_ARGV))),
            "invocations": [
                {"index": 1, "outcome": "ValueError: failed-preflight manifest drift",
                 "full_transcript_available": False},
                {"index": 2, "outcome": "ValueError: failed-preflight manifest drift",
                 "transcript_origin": "operator_captured_tmp_log",
                 "transcript_size": len(trace_raw), "transcript_sha256": base.sha_bytes(trace_raw),
                 "transcript_utf8": GEN3_INVOCATION_2_TRACE},
            ],
            "accidental_pre_ship_nvidia_smi": {
                "disclosed": True, "read_only": True, "used_as_launch_evidence": False,
                "repository_or_protocol_state_created": False,
            },
        },
        "mechanically_reproduced_source_control_flow": _gen3_control_flow_reproduction(),
        "mechanically_observed_current_absence": {
            "observed_at_utc": GEN3_FAILURE_OBSERVED_AT,
            "evidence_class": "current_state_not_historical_syscall_observation",
            "absent_paths": [str(path) for path in absent],
            "absent_derived_patterns": derived,
            "quarantined_lstat": quarantine,
            "sealed_payload_content_reads": 0,
        },
        "failed_gen3_subject": failed_entries,
        "gen5_implementation_subject": current_entries,
    }


def _typed_json_leaf_differences(
    left: Any, right: Any, pointer: str = "",
) -> list[dict[str, Any]]:
    """Return exact JSON-leaf differences with RFC-6901-style pointers."""
    if type(left) is not type(right):
        return [{"pointer": pointer or "/", "live": left, "candidate": right}]
    if isinstance(left, dict):
        differences: list[dict[str, Any]] = []
        keys = sorted(set(left) | set(right), key=lambda value: str(value).encode("utf-8"))
        for key in keys:
            escaped = str(key).replace("~", "~0").replace("/", "~1")
            child = f"{pointer}/{escaped}"
            if key not in left or key not in right:
                differences.append({"pointer": child, "live": left.get(key),
                                    "candidate": right.get(key)})
            else:
                differences.extend(_typed_json_leaf_differences(left[key], right[key], child))
        return differences
    if isinstance(left, list):
        differences = []
        for index in range(max(len(left), len(right))):
            child = f"{pointer}/{index}"
            if index >= len(left) or index >= len(right):
                differences.append({"pointer": child,
                                    "live": left[index] if index < len(left) else None,
                                    "candidate": right[index] if index < len(right) else None})
            else:
                differences.extend(
                    _typed_json_leaf_differences(left[index], right[index], child))
        return differences
    return [] if left == right else [
        {"pointer": pointer or "/", "live": left, "candidate": right}]


def _validate_gen2_terminal_namespace(*, require_failure: bool) -> None:
    """Close every gen2 child set without opening any quarantined payload."""
    _exact_directory_entries(predecessor_runtime.ACTIVE_CONFIG, {
        "protocol.json", "authorization_commitment.json", "ed25519_public.pem",
        "cpu_no_model_public_entry_trace.json",
    })
    _exact_directory_entries(
        predecessor_runtime.ACTIVE_PROV,
        {"m4_failure.json"} if require_failure else set())
    _exact_directory_entries(predecessor_runtime.ACTIVE_STATE, {"nonces"})
    _exact_directory_entries(predecessor_runtime.ACTIVE_NONCE_DIR, set())
    _exact_directory_entries(V3_DATA, {
        name for phase in ("M0", "M1", "M2")
        for name in base.V3_DATA_PHASE_FILES[phase]})
    for path in (predecessor_runtime.ACTIVE_CONFIG,
                 predecessor_runtime.ACTIVE_PROV,
                 predecessor_runtime.ACTIVE_STATE,
                 predecessor_runtime.ACTIVE_NONCE_DIR):
        st = path.lstat()
        if (stat.S_IMODE(st.st_mode) != 0o700 or st.st_uid != os.getuid()
                or not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)):
            raise ValueError(f"failed gen2 secure-directory drift: {path}")


def _rebuild_generic_config_at_synthetic_root(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Execute immutable generic-builder bytes with typed read-only path mapping."""
    builder_path = ROOT / "scripts/msae_independent_measurement_v3.py"
    _regular_entry(builder_path)
    module_name = f"_msae_gen2_failure_rooted_{os.getpid()}_{id(candidate_root)}"
    spec = continuation.source_only_module_spec(module_name, builder_path)
    if spec is None or spec.loader is None:
        raise ValueError("cannot load immutable generic builder for failure reproduction")
    rooted_builder = importlib.util.module_from_spec(spec)
    captured: list[dict[str, Any]] = []

    def live_alias(path: Path) -> Path:
        return (ROOT / path.relative_to(candidate_root)
                if path.is_relative_to(candidate_root) else path)

    try:
        sys.modules[module_name] = rooted_builder
        spec.loader.exec_module(rooted_builder)
        rooted_builder.ROOT = candidate_root
        rooted_builder.V3_CONFIG = candidate_root / "configs/msae_independent_measurement_v3"
        rooted_builder.__file__ = str(
            candidate_root / "scripts/msae_independent_measurement_v3.py")
        rooted_builder.read_json = lambda path: base.read_json(live_alias(Path(path)))
        rooted_builder.sha_file = lambda path: base.sha_file(live_alias(Path(path)))
        rooted_builder.install_json = lambda path, value: captured.append(value)
        value = rooted_builder.build_protocol_config(checkpoints)
    finally:
        sys.modules.pop(module_name, None)
    if len(captured) != 1 or captured[0] != value:
        raise AssertionError("synthetic-root generic config interception failed")
    return value


def _rebuild_gen2_config_at_synthetic_root(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Execute immutable generic + gen2 adapter code with no candidate-tree write."""
    rooted_generic = _rebuild_generic_config_at_synthetic_root(
        candidate_root, checkpoints)
    original_builder = base.build_protocol_config
    original_entry = predecessor_runtime._regular_entry

    def intercepted_builder(bound_checkpoints: list[dict[str, Any]]) -> dict[str, Any]:
        if bound_checkpoints != checkpoints:
            raise ValueError("synthetic gen2 checkpoint input drift")
        base.install_json(base.V3_CONFIG / "protocol.json", rooted_generic)
        return rooted_generic

    def rooted_entry(path: Path, *, root: Path) -> dict[str, Any]:
        if root != candidate_root or not path.is_relative_to(candidate_root):
            raise ValueError("synthetic gen2 adapter attempted a non-rooted local entry")
        live_path = ROOT / path.relative_to(candidate_root)
        return original_entry(live_path, root=ROOT)

    try:
        base.build_protocol_config = intercepted_builder
        predecessor_runtime._regular_entry = rooted_entry
        return predecessor_runtime._protocol_config_payload(
            checkpoints, M2_REVIEWED_COMPLETION_SHA256, root=candidate_root)
    finally:
        base.build_protocol_config = original_builder
        predecessor_runtime._regular_entry = original_entry


def _gen2_failure_payload(
    predicted_gen3_terminal: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Reconstruct gen2's failed-M4 terminal record without rerunning M4."""
    expected_config_sha = "0abb5276f5241fc8bd206b271d63a11ece254adbbf6f66cc54f414121ce73c4e"
    expected_trace_sha = "0d9ce79822888aa8096018e3b271cf15fb0a02044c7a2d1af41afa28423e3ce2"
    predecessor_runtime.verify_m2_completion(M2_REVIEWED_COMPLETION_SHA256)
    predecessor_runtime._verify_existing_authorization_state()
    _validate_gen2_terminal_namespace(
        require_failure=_path_present(GEN2_FAILURE_PATH))
    trace_raw = predecessor_runtime._regular_bytes(
        predecessor_runtime.CPU_NO_MODEL_TRACE, mode=0o644)
    if base.sha_bytes(trace_raw) != expected_trace_sha:
        raise ValueError("failed gen2 CPU/no-model trace digest drift")
    trace_value = base.strict_json_loads(trace_raw.decode("utf-8"))
    if trace_raw != base.canonical_bytes(trace_value):
        raise ValueError("failed gen2 CPU/no-model trace canonical bytes drift")
    predecessor_runtime._validate_cpu_no_model_trace(
        trace_value, root=ROOT, checkpoints=predecessor_runtime.checkpoint_registry())
    gen2_config_path = predecessor_runtime.ACTIVE_CONFIG / "protocol.json"
    gen2_config_raw = predecessor_runtime._regular_bytes(gen2_config_path, mode=0o644)
    if base.sha_bytes(gen2_config_raw) != expected_config_sha:
        raise ValueError("failed gen2 M3 protocol config drift")
    gen2_config = base.strict_json_loads(gen2_config_raw.decode("utf-8"))
    if gen2_config_raw != base.canonical_bytes(gen2_config):
        raise ValueError("failed gen2 M3 protocol config is noncanonical")
    if gen2_config.get("post_m2_runtime", {}).get("generation") != "post_m2_gen2":
        raise ValueError("failed gen2 M3 generation drift")
    if any(predecessor_runtime.ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("failed gen2 nonce directory is not empty")
    absent_paths = [
        *(ROOT / relative for relative in predecessor_runtime.M4_NEW),
        predecessor_runtime.M4_TRANSACTION,
        predecessor_runtime.PRESCORE_REVIEW,
        predecessor_runtime.ACTIVE_RUN_ROOT,
        predecessor_runtime.M4_PRIMARY,
        predecessor_runtime.M4_REBUILD,
    ]
    for path in absent_paths:
        if _path_present(path):
            raise ValueError(f"failed gen2 downstream output unexpectedly exists: {path}")
    for pattern in _post_m3_forbidden_tmp_patterns()[3:]:
        matches = sorted(Path("/tmp").glob(pattern))
        if matches:
            raise ValueError(f"failed gen2 derived output unexpectedly exists: {matches}")
    quarantine = []
    for relative in sorted(base.QUARANTINED):
        path = ROOT / relative
        st = path.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or stat.S_IMODE(st.st_mode) != 0o600 or st.st_nlink != 1):
            raise ValueError(f"failed gen2 quarantine identity drift: {relative}")
        quarantine.append({"path": relative, "device": st.st_dev, "inode": st.st_ino,
                           "uid": st.st_uid, "mode": stat.S_IMODE(st.st_mode),
                           "size": st.st_size, "nlink": st.st_nlink,
                           "content_read": False})
    generic = predecessor_runtime.generic_config_projection(gen2_config)
    live_environment = base.sha_bytes(base.canonical_bytes({
        "python": str((ROOT / ".venv-atlas/bin/python").resolve()),
        "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }))
    synthetic_root = Path("/tmp/msae_independent_measurement_v3_gen2_failure_reproduction")
    rooted_environment = base.sha_bytes(base.canonical_bytes({
        "python": str((synthetic_root / ".venv-atlas/bin/python").resolve()),
        "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }))
    strata = generic["replay"]["strata"]
    if len(strata) != 4 or any(row.get("environment_sha256") != live_environment
                               for row in strata):
        raise ValueError("failed gen2 environment reproduction precondition drift")
    candidate_config = _rebuild_gen2_config_at_synthetic_root(
        synthetic_root, list(gen2_config["checkpoint_registry"]))
    candidate_generic = predecessor_runtime.generic_config_projection(candidate_config)
    rooted_strata = candidate_generic.get("replay", {}).get("strata")
    if (not isinstance(rooted_strata, list) or len(rooted_strata) != 4
            or any(row.get("environment_sha256") != rooted_environment
                   for row in rooted_strata)):
        raise ValueError("failed gen2 synthetic-root builder environment drift")
    # The immutable failed Stage-A compared the full successor config, not only
    # its generic projection.  Prove that the complete gen2 candidate differs
    # at exactly the same four root-dependent leaves before reporting cause.
    differences = _typed_json_leaf_differences(gen2_config, candidate_config)
    pointers = [row["pointer"] for row in differences]
    expected_pointers = [f"/replay/strata/{index}/environment_sha256"
                         for index in range(len(strata))]
    if pointers != expected_pointers or any(
            row["live"] != live_environment or row["candidate"] != rooted_environment
            for row in differences):
        raise ValueError(f"failed gen2 typed root-cause diff drift: {differences}")
    config_entries = [_regular_entry(predecessor_runtime.ACTIVE_CONFIG / name)
                      for name in ("protocol.json", "authorization_commitment.json",
                                   "ed25519_public.pem",
                                   "cpu_no_model_public_entry_trace.json")]
    private_st = predecessor_runtime.ACTIVE_PRIVATE_KEY.lstat()
    payload = {
        "schema_version": "msae_v3_gen2_m4_failure_v1",
        "protocol_id": PROTOCOL,
        "generation": "post_m2_gen2",
        "status": "failed_before_stage_a_during_m4",
        "historical_failure": {
            "evidence_class": "operator_attested",
            "command": (".venv-atlas/bin/python -S -B -I "
                        "scripts/msae_independent_measurement_v3_post_m1.py build-m4"),
            "error_type": "ValueError",
            "error": "active protocol config does not reproduce",
            "full_original_transcript_available": False,
        },
        "independent_root_cause_reproduction": {
            "method": ("immutable_generic_builder_and_gen2_adapter_execution_at_fixed_"
                       "synthetic_candidate_root"),
            "generic_builder_entry": _regular_entry(
                ROOT / "scripts/msae_independent_measurement_v3.py"),
            "synthetic_candidate_root": str(synthetic_root),
            "live_environment_sha256": live_environment,
            "candidate_root_environment_sha256": rooted_environment,
            "differing_json_pointers": pointers,
            "field_differences": differences,
            "differing_field_count": len(differences),
            "all_other_generic_fields_unchanged": pointers == expected_pointers,
            "cause": "generic_builder_environment_python_path_depends_on_candidate_ROOT",
        },
        "m3_config_entries": config_entries,
        "m3_config_entry_set_sha256": base.sha_bytes(base.canonical_bytes(config_entries)),
        "private_key_lstat": {
            "path": str(predecessor_runtime.ACTIVE_PRIVATE_KEY),
            "device": private_st.st_dev, "inode": private_st.st_ino,
            "uid": private_st.st_uid, "mode": stat.S_IMODE(private_st.st_mode),
            "size": private_st.st_size, "nlink": private_st.st_nlink,
            "public_binding_independently_verified": True,
        },
        "quarantined_lstat": quarantine,
        "sealed_payload_content_reads": 0,
        "stage_a": "not_created", "m4_outputs": "not_created",
        "prescore_review": "not_created", "authorization_signature": "not_created",
        "model_gpu_tmux": "not_run", "successor_generation": GENERATION,
    }
    terminal = (_gen3_terminal_payload() if predicted_gen3_terminal is None
                else dict(predicted_gen3_terminal))
    payload["writer_generation"] = GENERATION
    payload["scientific_predecessor_subject"] = {
        "m1_completion_sha256": M1_REVIEWED_COMPLETION_SHA256,
        "m2_completion_sha256": M2_REVIEWED_COMPLETION_SHA256,
    }
    payload["failed_gen3_terminal_sha256"] = base.sha_bytes(base.canonical_bytes(terminal))
    payload["gen5_plan_authority"] = {
        "plan_sha256": FROZEN_PLAN_SHA256,
        "plan_review_sha256": FROZEN_PLAN_REVIEW_SHA256,
    }
    payload["gen5_implementation_subject"] = _current_gen5_entries()
    return payload


